BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-22718'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='BTR003' OR source_url ~ '[?&]id=22718(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='821ab003-5ec8-4de4-b05e-409047622718' OR slug='sam-kham-ngern-holiday-homes-cha-am-btr003' OR (abs(latitude-12.780596)<0.0001 AND abs(longitude-99.978297)<0.0001 AND abs(land_area_sqm-8640)<1)) THEN RAISE NOTICE 'SAM BTR003 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, custom_project_name, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('821ab003-5ec8-4de4-b05e-409047622718', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'hotel_resort', 'business', 'sale', 'whole_property', 'บ้านพักขามเงิน ชะอำ ติดถนน 2 ด้าน 5 ไร่ 1 งาน 60 ตร.ว.', 'รายละเอียดทรัพย์

บ้านพักตากอากาศขามเงิน ถนนร่วมจิตต์ ตำบลชะอำ อำเภอชะอำ จังหวัดเพชรบุรี เนื้อที่รวมตามหน้า SAM 5 ไร่ 1 งาน 60 ตร.ว. หรือ 2,160 ตร.ว. (8,640 ตร.ม.) ราคาประกาศขาย SAM 167,244,000 บาท รหัส BTR003 เป็นการขายทั้งทรัพย์

ส่วนสรุปเอกสารสิทธิ์ระบุโฉนด 9029, 9030, 44861, 44862 และ 44863 รวม 5 ฉบับ แต่คำบรรยายระบุที่ดิน 8 แปลงติดกัน และมีเลข 44962 ในรายการสิ่งปลูกสร้าง ซึ่งต่างจากเลข 44862 ในส่วนสรุป จึงแสดงรายการโฉนดตามส่วนสรุปโดยไม่เพิ่มเลขที่ไม่ยืนยัน ผู้สนใจต้องยืนยันจำนวนแปลง เลขโฉนดและพื้นที่กับ SAM ก่อนเสนอซื้อ

ที่ดินตามคำบรรยายเป็นรูปสี่เหลี่ยมผืนผ้า ติดถนน 2 ด้าน ด้านตะวันออกและตะวันตกกว้างประมาณด้านละ 50 เมตร ลึกประมาณ 165 เมตร ด้านหน้าถนนร่วมจิตต์อยู่ฝั่งตรงข้ามชายหาดตามผัง SAM ไม่ใช่การขายชายหาดส่วนตัว ถนนร่วมจิตต์ตาม SAM เป็นทางสาธารณะ ผิวลาดยางกว้างประมาณ 8 เมตร เขตทางประมาณ 12 เมตร อีกด้านตามภาพเป็นถนนเจ้าลาย

สิ่งปลูกสร้างและเงื่อนไขการโอน

คำบรรยายสำรวจระบุบ้านพักตากอากาศชื่อบ้านพักขามเงิน รวม 13 หลัง ตัวเลขนี้เป็นจำนวนบ้านพักตามสำรวจ ไม่ใช่จำนวนห้องนอน และไม่ใช่การยืนยันว่าทุกหลังอยู่ในรายการโอน

รายการรับโอนบนโฉนด 9029 เป็นร้านอาหารและบ้านพักอาศัยชั้นเดียวที่ใช้เป็นร้านกาแฟสด บนโฉนด 9030 เป็นบ้านพักอาศัยชั้นเดียว 8 หลังและบ้านพักอาศัยชั้นเดียวอีก 1 หลัง บนโฉนด 44863 เป็นบ้านพักอาศัยชั้นเดียว ส่วนคำบรรยายระบุโฉนด 44861 และ 44962 ไม่มีสิ่งปลูกสร้าง โดยเลข 44962 ต้องตรวจสอบเทียบกับส่วนสรุปดังกล่าว

SAM กำหนดว่าจะโอนสิ่งปลูกสร้างตามรายการที่จดทะเบียนรับโอนเท่านั้น ผังสิ่งปลูกสร้างมีหลายรายการและระบุบางรายการรื้อถอนแล้ว จึงควรตรวจเทียบทะเบียน ผัง และสภาพจริงก่อนเสนอซื้อ ต้นทางไม่ยืนยันสถานะเปิดกิจการ รายได้ จำนวนห้องพัก ใบอนุญาตหรือสภาพภายในปัจจุบัน

ข้อควรทราบเรื่องการก่อสร้าง

SAM ระบุผังเมืองสีชมพู และอ้างประกาศกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม พ.ศ.2561 ว่าทรัพย์อยู่ในเขตควบคุมการก่อสร้างริมทะเลชะอำ ปลูกสร้างได้สูงไม่เกิน 12 เมตร ข้อมูลนี้เป็นข้อกำหนดที่ต้นทางอ้าง ไม่ใช่การยืนยันการอนุญาตก่อสร้าง ผู้สนใจควรตรวจข้อกำหนดปัจจุบัน แนวเขตและแผนพัฒนากับหน่วยงานก่อนตัดสินใจ

ทำเลและการเดินทาง

อยู่ในย่านที่อยู่อาศัยและแหล่งท่องเที่ยว ใกล้ชายหาดชะอำ โรงพยาบาลชะอำ โรงเรียนเทศบาล 8 สวนสนชะอำและคริสตจักรชะอำ ตาม SAM จากท่ายางมุ่งหน้าหัวหินบนถนนเพชรเกษม (ทล.4) ผ่านวนอุทยานชะอำ เลี้ยวซ้ายเข้าถนนหนองแจงไปทางชายหาด แล้วเลี้ยวซ้ายเข้าถนนร่วมจิตต์ ผ่านซอยชะอำใต้ 6 ทรัพย์อยู่ซ้ายมือ

ภาพและข้อมูลต้นทาง

ภาพจริงและผังจาก SAM รวม 9 ภาพ ภาพภายนอกแสดงวันที่ 28 กุมภาพันธ์ 2568 ควรตรวจสภาพปัจจุบัน พิกัด 12.780596, 99.978297 ดึงจากลิงก์นำทาง SAM และตรงกับลิงก์แผนที่ เป็นจุดอ้างอิง ไม่ใช่แนวเขตรังวัด ราคาและสถานะซื้อตรงตรวจวันที่ 15 กันยายน 2569 ติดต่อ SAM 02-686-1888, sales@sam.or.th หรือ LINE @samline แจ้งรหัส BTR003 เพื่อยืนยันเอกสารสิทธิ์ สิ่งปลูกสร้าง ราคาและเงื่อนไขล่าสุด', 167244000, false, 8640, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'บ้านพักขามเงิน', 'บ้านพักขามเงิน ถนนร่วมจิตต์', 'อีกด้านติดถนนเจ้าลายตามภาพต้นทาง', 'ถนนร่วมจิตต์', 12.780596, 99.978297, 'เพชรบุรี', 'ชะอำ', 'ชะอำ', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-kham-ngern-holiday-homes-cha-am-btr003') RETURNING id INTO property_listing_id;
