INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=22718&keyref=', 'BTR003', now(), 'Checked2026-09-15. THB167244000,8640sqm. Summary5titles vs narrative8plots;44862/44962 mismatch retained for verification.13surveyed houses not room count;registered inventory only transfer. Coastal2018 source height12m,current rules unconfirmed.9authentic photos/plans,field date2025-02-28. Navigation/map agree. Source/page/deed/nearby duplicate query and map filenameLL0052 alias search empty.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Kham Ngern Holiday Homes, Cha-am — Two Road Frontages, THB167.244M', 'Kham Ngern holiday-home property on Ruam Chit Road,Cha-am,Phetchaburi. SAM summary area5 rai1 ngan60sq.wah,or2,160sq.wah (8,640sq.m.). Whole-property announced price THB167,244,000,asset BTR003.

Source discrepancy: summary lists five Chanote certificates9029,9030,44861,44862,44863,while narrative says eight adjoining plots and mentions44962 instead of44862 in the building inventory. Listed title numbers follow the summary; no unconfirmed title is added. Verify plot count,title numbers and area with SAM.

Narrative describes a rectangular site with roads on two sides,approximately50m east/west frontage and165m depth. The source plan places Ruam Chit Road between the property and beach; no private-beach ownership is claimed. SAM describes Ruam Chit as public,8m paved carriageway and12m right of way. The opposite road is labelled Chao Lai in source photos.

Survey describes13 holiday houses called Kham Ngern. This is a house count,not bedroom/guest-room count or confirmation all are transferred. Registered inventory: restaurant and single-storey house used as coffee shop on9029;eight single-storey houses plus another single-storey house on9030;one single-storey house on44863. Narrative says44861 and44962 have no buildings,the latter requiring reconciliation with summary44862.

SAM explicitly transfers only structures in its registered acquisition inventory. The building plan lists multiple structures,some labelled demolished. Reconcile registration,plan and current condition before purchase. Current operating status,income,room count,licences and interior condition are not confirmed by source.

SAM reports pink zoning and cites a2018 environmental-protection notice for Cha-am coastal construction limiting height to12m. This is source-attributed information,not confirmation of permission;verify current rules,boundaries and proposed development with authorities.

Residential/tourism surroundings near Cha-am Beach,Cha-am Hospital,municipal school8 Suan Son and Cha-am church. From Tha Yang toward Hua Hin on Phetkasem Highway4,past Cha-am Forest Park,turn left into Nong Chaeng Road toward the beach,then left into Ruam Chit Road,past Cha-am Tai6;property left.

